SELECT airports.City, flights.Airline, flights.FlightNo, flights.DestAirport, flights.SourceAirport FROM airports JOIN flights ON airports.AirportCode = flights.SourceAirport GROUP BY airports.City ORDER BY flights.Airline DESC LIMIT 1;
SELECT airports.AirportName, flights.SourceAirport, flights.DestAirport FROM airports INNER JOIN flights ON airports.AirportCode = flights.SourceAirport GROUP BY airports.AirportCode ORDER BY COUNT(*) DESC LIMIT 1;
