SELECT DISTINCT airports.AirportName FROM airports JOIN flights ON airports.AirportCode = flights.SourceAirport GROUP BY airports.AirportName ORDER BY COUNT(*) DESC LIMIT 1;
SELECT airports.AirportCode FROM airports JOIN flights ON airports.AirportCode = flights.SourceAirport GROUP BY airports.AirportCode ORDER BY flights.SourceAirport DESC LIMIT 1;
SELECT airports.AirportCode FROM airports JOIN flights ON airports.AirportCode = flights.SourceAirport GROUP BY airports.AirportCode ORDER BY COUNT(*) DESC LIMIT 1
SELECT airports.AirportCode FROM airports JOIN flights ON airports.AirportCode = flights.SourceAirport GROUP BY airports.AirportCode ORDER BY COUNT(flights.SourceAirport) DESC LIMIT 1
SELECT airports.AirportCode, flights.Airline, flights.FlightNo, flights.SourceAirport, flights.DestAirport FROM flights JOIN airports ON flights.SourceAirport = airports.AirportCode ORDER BY flights.SourceAirport ASC;
