SELECT COUNT(*) FROM employee;
SELECT COUNT(*) FROM employee;
SELECT Name FROM employee ORDER BY Age ASC;
SELECT e.Name, e.Age FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID ORDER BY e.Age ASC;
SELECT DISTINCT employee.City, COUNT(employee.Employee_ID) AS worker_count FROM employee JOIN hiring ON employee.Employee_ID = hiring.Employee_ID GROUP BY employee.City;
SELECT COUNT(*) AS total_staffs, town FROM employee JOIN hiring ON hiring.Shop_ID = shop.Shop_ID GROUP BY town
SELECT e.Name, e.Age, e.City, h.Manager_name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN shop s ON h.Shop_ID = s.Shop_ID WHERE e.Age < 30 AND h.Is_full_time = 1 AND h.Manager_name IS NOT NULL AND h.Shop_ID IS NOT NULL
SELECT e.Name, e.City FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID WHERE h.Start_from <= 30 AND h.Is_full_time = 1;
SELECT COUNT(*) AS total_shops_per_city, City FROM employee JOIN shop ON employee.City = shop.City GROUP BY City;
SELECT COUNT(*) AS total_stores, City FROM employee JOIN shop ON employee.City = shop.District GROUP BY City;
SELECT e.Name, shop.District FROM employee e JOIN shop ON e.Employee_ID = hiring.Employee_ID JOIN shop ON hiring.Shop_ID = shop.Shop_ID WHERE shop.Number_products = (SELECT MAX(Number_products) FROM shop)
SELECT e.Name, s.District FROM employee e INNER JOIN shop s ON e.Employee_ID = s.Manager_name;
SELECT MIN(Number_products) AS min_products, MAX(Number_products) AS max_products FROM shop;
SELECT MIN(Number_products) AS min_number_of_goods, MAX(Number_products) AS max_number_of_goods FROM shop;
SELECT e.Name, e.City, e.District FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID ORDER BY h.Number_products DESC;
SELECT Name, City, District FROM employee JOIN shop ON employee.Employee_ID = shop.Manager_name ORDER BY Number_products DESC;
SELECT e.Name AS Store_Name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID WHERE h.Shop_ID IN (SELECT Shop_ID FROM shop WHERE Number_products > (SELECT AVG(Number_products) FROM shop))
SELECT e.Name AS Store_Name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN shop s ON h.Shop_ID = s.Shop_ID WHERE s.Number_products > (SELECT AVG(Number_products) FROM shop)
SELECT e.Name, e.Age, e.City, e.Manager_name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN evaluation e2 ON e.Employee_ID = e2.Employee_ID GROUP BY e.Employee_ID ORDER BY e2.Bonus DESC;
SELECT Name FROM employee JOIN evaluation ON employee.Employee_ID = evaluation.Employee_ID ORDER BY Bonus DESC LIMIT 1
SELECT e.Name AS Name, e.Age, e.City, e.Manager_name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN evaluation e2 ON e.Employee_ID = e2.Employee_ID ORDER BY e2.Bonus DESC LIMIT 1;
SELECT Name FROM employee ORDER BY Bonus DESC LIMIT 1
SELECT e.Name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN evaluation e2 ON h.Shop_ID = e2.Employee_ID WHERE e2.Year_awarded IS NULL;
SELECT e.Name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID WHERE e.Manager_name IS NULL;
SELECT e.Name, h.Shop_ID FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID GROUP BY e.Name ORDER BY h.Shop_ID DESC LIMIT 1
SELECT shop.Name FROM shop JOIN employee ON shop.Shop_ID = hiring.Shop_ID JOIN employee ON hiring.Employee_ID = employee.Employee_ID WHERE employee.Age > 30;
SELECT e.Name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID WHERE h.Is_full_time = 'N' AND h.Shop_ID IS NULL;
SELECT e.Name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID WHERE h.Is_full_time = FALSE;
SELECT e.Name, COUNT(e.Employee_ID) AS total_staffs FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID GROUP BY e.Name;
SELECT e.Name, COUNT(e.Employee_ID) AS total_people FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID GROUP BY e.Name
SELECT SUM(evaluation.Bonus) AS total_premium FROM evaluation JOIN employee ON evaluation.Employee_ID = employee.Employee_ID
SELECT SUM(evaluation.Bonus) AS total_extra_prize FROM evaluation JOIN employee ON evaluation.Employee_ID = employee.Employee_ID;
SELECT e.Name, h.Shop_ID, h.Is_full_time FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID
SELECT e.Name, e.Age, e.City, h.Shop_ID, h.Is_full_time, e.Manager_name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID;
