SELECT Templates.Template_ID, Templates.Name, Templates.Description FROM Templates;
SELECT Documents.Document_Name, Templates.Template_Type_Code FROM Documents INNER JOIN Templates ON Documents.Template_ID = Templates.Template_ID WHERE Templates.Template_Type_Description LIKE '%w%';
SELECT D.Document_Name, P.Other_Details FROM Documents D JOIN Paragraphs P ON D.Document_ID = P.Document_ID WHERE D.Template_Details LIKE '%w%';
SELECT Template_ID, Template_Details, Document_Description FROM Templates INNER JOIN Documents ON Templates.Template_ID = Documents.Template_ID WHERE Document_Name = 'Robbin CV';
SELECT Templates.Template_ID, Templates.Template_Type_Code, Templates.Template_Details FROM Templates INNER JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Templates.Template_Details LIKE '%Robbin CV%'
