SELECT COUNT(DISTINCT Template_Type_Description) FROM Ref_Template_Types;
SELECT COUNT(DISTINCT Document_ID) FROM Documents WHERE Document_Description LIKE '%PPT%'
SELECT COUNT(DOCUMENTS.Document_ID) FROM Documents JOIN Templates ON Documents.Template_ID = Templates.Template_ID JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Template_Type_Description = 'PPT'
SELECT Template_Type_Code, COUNT(DOCUMENTS.Document_ID) AS Document_Count FROM Templates JOIN Documents ON Templates.Template_Type_Code = Documents.Template_ID GROUP BY Template_Type_Code;
SELECT Template_Type_Code, COUNT(Document_ID) AS Document_Upsell_count FROM Templates JOIN Documents ON Templates.Template_Type_Code = Documents.Template_ID JOIN Paragraphs ON Documents.Document_ID = Paragraphs.Document_ID GROUP BY Template_Type_Code
SELECT Template_ID, Template_Type_Code FROM Templates INNER JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Date_Effective_To IS NULL OR Date_Effective_To IS NULL;
SELECT Templates.Template_ID, Templates.Template_Type_Code FROM Templates JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Templates.Date_Effective_To IS NULL OR Templates.Date_Effective_To IS NULL;
SELECT Template_ID FROM Templates JOIN Documents ON Templates.Template_ID = Documents.Template_ID JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Document_ID IN (SELECT Document_ID FROM Documents JOIN Templates ON Templates.Template_ID = Documents.Template_ID GROUP BY Templates.Template_ID HAVING COUNT(Document_ID) > 1)
SELECT Templates.Template_ID FROM Templates INNER JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Templates.Template_Type_Code IS NOT NULL AND Templates.Date_Effective_To IS NOT NULL AND Templates.Date_Effective_To > (SELECT MAX(Date_Effective_To) FROM Templates WHERE Date_Effective_To IS NOT NULL)
SELECT Templates.Template_ID FROM Templates JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Templates.Template_Type_Code IS NOT NULL AND Templates.Template_Type_Code NOT IN (SELECT Template_Type_Code FROM Documents JOIN Templates ON Documents.Template_ID = Templates.Template_ID)
SELECT Templates.Template_ID FROM Templates JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Template_Details IS NULL;
