SELECT Template_Type_Code, COUNT(DOCUMENTS.Document_ID) AS NumLayouts FROM Templates INNER JOIN Documents ON Templates.Template_Type_Code = Documents.Template_ID GROUP BY Template_Type_Code
SELECT Template_Type_Description, COUNT(*) AS Total_layouts FROM Templates JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code GROUP BY Template_Type_Description
SELECT Ref_Template_Types.Template_Type_Code, COUNT(Paragraphs.Document_ID) AS total_layouts FROM Templates JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code JOIN Paragraphs ON Templates.Template_ID = Paragraphs.Document_ID GROUP BY Ref_Template_Types.Template_Type_Code ORDER BY total_layouts DESC
