SELECT Templates.Template_Type_Code FROM Templates INNER JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Templates.Document_ID = (SELECT Document_ID FROM Documents WHERE Document_Name = 'Data base')
