SELECT D.Document_Name, D.Template_ID, D.Template_Details, D.Other_Details, D.Document_Description FROM Documents D JOIN Templates T ON D.Template_ID = T.Template_ID JOIN Ref_Template_Types RT ON T.Template_Type_Code = RT.Template_Type_Code WHERE RT.Template_Type_Description = 'BK';
SELECT Template_Type_Description, COUNT(Document_ID) AS num_papers FROM Templates JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code GROUP BY Template_Type_Description
