SELECT Document_ID, Template_Details, Other_Details FROM Documents INNER JOIN Templates ON Documents.Template_ID = Templates.Template_ID WHERE Template_Details LIKE '%Korea%'
SELECT Paragraphs.Paragraph_ID, Paragraphs.Other_Details FROM Paragraphs JOIN Documents ON Documents.Document_ID = Paragraphs.Document_ID JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Document_Name = 'Welcome to NY' AND Templates.Template_Details IS NOT NULL;
SELECT Paragraphs.Para_ID, Paragraphs.Template_ID, Paragraphs.Other_Details FROM Paragraphs INNER JOIN Templates ON Templates.Template_ID = Paragraphs.Document_ID INNER JOIN Documents ON Documents.Template_ID = Templates.Template_ID WHERE Documents.Document_Name = 'Welcome to NY' AND Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code;
SELECT Paragraph_Text, Other_Details FROM Paragraphs;
SELECT Paragraphs.Paragraph_Text FROM Paragraphs JOIN Documents ON Paragraphs.Document_ID = Documents.Document_ID WHERE Documents.Document_Name = 'Customer reviews'
SELECT Templates.Template_ID, COUNT(Paragraphs.Paragraph_ID) AS Paragraphs_Count FROM Templates JOIN Paragraphs ON Templates.Template_ID = Paragraphs.Document_ID GROUP BY Templates.Template_ID ORDER BY Templates.Template_ID;
SELECT DISTINCT Template_ID, COUNT(Paragraph_ID) AS Paragraph_Count FROM Templates INNER JOIN Paragraphs ON Templates.Template_ID = Paragraphs.Document_ID GROUP BY Template_ID ORDER BY Template_ID
SELECT Template_ID, Document_Name, COUNT(Paragraph_Text) AS Paragraph_Count FROM Templates INNER JOIN Documents ON Templates.Template_ID = Documents.Template_ID INNER JOIN Paragraphs ON Documents.Document_ID = Paragraphs.Document_ID GROUP BY Template_ID, Document_Name;
SELECT Templates.Template_ID, Templates.Template_Details, COUNT(Paragraphs.Paragraph_ID) AS Paragraphs_Count FROM Templates INNER JOIN Paragraphs ON Templates.Template_ID = Paragraphs.Document_ID;
SELECT Template_ID, Template_Details FROM Templates INNER JOIN Documents ON Templates.Template_ID = Documents.Template_ID INNER JOIN Paragraphs ON Documents.Document_ID = Paragraphs.Document_ID WHERE Paragraphs.Other_Details IS NOT NULL AND COUNT(Paragraphs.Other_Details) >= 2;
SELECT D.Document_ID FROM Documents D JOIN Templates T ON D.Template_ID = T.Template_ID JOIN Paragraphs P ON D.Document_ID = P.Document_ID WHERE P.Paragraph_Text IS NOT NULL AND P.Paragraph_Text LIKE '%2%'
SELECT Document_ID, Document_Name, COUNT(Paragraph_ID) AS paragraph_count FROM Paragraphs JOIN Templates ON Paragraphs.Document_ID = Templates.Template_ID GROUP BY Document_ID ORDER BY COUNT(Paragraph_ID) DESC;
SELECT Templates.Template_ID, Templates.Template_Details FROM Templates JOIN Documents ON Templates.Template_ID = Documents.Template_ID JOIN Paragraphs ON Documents.Document_ID = Paragraphs.Document_ID GROUP BY Templates.Template_ID ORDER BY Paragraphs.Paragraph_Text DESC LIMIT 1;
SELECT Templates.Template_ID, Templates.Template_Type_Code, Templates.Date_Effective_To, Templates.Date_Effective_From, Templates.Template_Details, Documents.Document_Name, Documents.Document_Description, Documents.Other_Details FROM Templates JOIN Documents ON Templates.Template_ID = Documents.Template_ID JOIN Ref_Template_Types ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code WHERE Documents.Document_ID IS NULL AND Templates.Template_Type_Code IS NULL
SELECT Templates.Template_ID FROM Templates JOIN Documents ON Templates.Template_ID = Documents.Document_ID JOIN Paragraphs ON Documents.Document_ID = Paragraphs.Document_ID WHERE Paragraphs.Other_Details IS NULL AND Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code ORDER BY Templates.Template_ID ASC;
SELECT Document_ID, Template_ID, Template_Details FROM Templates INNER JOIN Documents ON Templates.Template_ID = Documents.Document_ID INNER JOIN Paragraphs ON Documents.Document_ID = Paragraphs.Document_ID WHERE Template_Details IS NOT NULL AND Document_ID = 1 OR Document_ID = 2;
SELECT D.Document_ID, D.Document_Name, D.Other_Details FROM Documents D JOIN Templates T ON D.Template_ID = T.Template_ID JOIN Paragraphs P ON D.Document_ID = P.Document_ID WHERE T.Template_Type_Code = ? AND P.Paragraph_Text IS NOT NULL;
SELECT Paragraphs.Paper_ID, Paragraphs.Paragraph_Text, Paragraphs.Other_Details FROM Paragraphs INNER JOIN Templates ON Templates.Template_Type_Code = Ref_Template_Types.Template_Type_Code AND Templates.Date_Effective_To = 'Ireland' AND Templates.Date_Effective_From = 'Brazil' AND Documents.Document_ID = Paragraphs.Document_ID;
SELECT D.Document_ID, P.Paragraph_ID FROM Documents D JOIN Paragraphs P ON D.Document_ID = P.Document_ID WHERE P.Paragraph_Text = 'Brazil' OR P.Paragraph_Text = 'Ireland';
SELECT COUNT(*) FROM teacher;
SELECT COUNT(*) FROM course_arrange;
SELECT teacher.Name, teacher.Age FROM teacher ORDER BY teacher.Age ASC;
SELECT Name FROM teacher ORDER BY Age ASC;
