SELECT teacher.Name FROM teacher INNER JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID INNER JOIN course ON course.Course_ID = course_arrange.Course_ID WHERE teacher.Age >= 32 OR teacher.Age = 33;
SELECT teacher.Name, teacher.Age FROM teacher JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID WHERE teacher.Age = 32 OR teacher.Age = 33;
SELECT teacher.Hometown, course_arrange.Course_ID FROM course_arrange JOIN teacher ON course_arrange.Teacher_ID = teacher.Teacher_ID ORDER BY teacher.Age ASC LIMIT 1;
SELECT DISTINCT teacher.Name, teacher.Age FROM teacher JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID JOIN course ON course.Course_ID = course_arrange.Course_ID WHERE course_arrange.Teacher_ID = teacher.Teacher_ID ORDER BY teacher.Age ASC;
SELECT teacher.Hometown, COUNT(teacher.Hometown) AS instructor_count FROM teacher JOIN course_arrange ON course_arrange.Teacher_ID = teacher.Teacher_ID GROUP BY teacher.Hometown
SELECT COUNT(DISTINCT teacher.Hometown) AS instructors_per_birthplace FROM course_arrange INNER JOIN teacher ON course_arrange.Teacher_ID = teacher.Teacher_ID GROUP BY teacher.Hometown;
SELECT DISTINCT teacher.Hometown FROM teacher JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID JOIN course ON course.Course_ID = course_arrange.Course_ID ORDER BY teacher.Hometown ASC
SELECT DISTINCT course.Course_ID, teacher.Name, teacher.Hometown, course_arrange.Course_ID, course_arrange.Grade FROM course JOIN teacher ON course.Course_ID = course_arrange.Course_ID JOIN course_arrange ON course.Course_ID = course_arrange.Course_ID;
SELECT DISTINCT t.Hometown FROM teacher t JOIN course_arrange ca ON t.Teacher_ID = ca.Teacher_ID JOIN course c ON ca.Course_ID = c.Course_ID WHERE c.Course_ID IN (SELECT Course_ID FROM course_arrange WHERE Teacher_ID = (SELECT Teacher_ID FROM teacher WHERE Name = 'Some Faculty Name'))
SELECT DISTINCT t.Name, c.Course_ID FROM course c JOIN course_arrange ca ON c.Course_ID = ca.Course_ID JOIN teacher t ON ca.Teacher_ID = t.Teacher_ID GROUP BY t.Name, c.Course_ID
SELECT teacher.Name, course.Course_ID FROM course INNER JOIN course_arrange ON course.Course_ID = course_arrange.Course_ID INNER JOIN teacher ON course_arrange.Teacher_ID = teacher.Teacher_ID;
SELECT course_arrange.Course_ID, course.Course, teacher.Name, teacher.Age, teacher.Hometown FROM course JOIN course_arrange ON course.Course_ID = course_arrange.Course_ID JOIN teacher ON course_arrange.Teacher_ID = teacher.Teacher_ID;
SELECT DISTINCT t.Name, c.Course_ID FROM teacher t JOIN course_arrange ca ON t.Teacher_ID = ca.Teacher_ID JOIN course c ON ca.Course_ID = c.Course_ID ORDER BY t.Name ASC;
SELECT DISTINCT teacher.Name, course.Course_ID FROM course JOIN course_arrange ON course.Course_ID = course_arrange.Course_ID JOIN teacher ON course_arrange.Teacher_ID = teacher.Teacher_ID ORDER BY teacher.Name ASC;
SELECT teacher.Name AS Faculty_Name FROM teacher JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID JOIN course ON course.Course_ID = course_arrange.Course_ID;
SELECT teacher.Name FROM teacher JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID JOIN course ON course.Course_ID = course_arrange.Course_ID WHERE course.Course = 'Math'
SELECT DISTINCT teacher.Name, COUNT(course_arrange.Course_ID) AS num_curriculums FROM teacher INNER JOIN course_arrange ON teacher.Teacher_ID = course_arrange.Teacher_ID GROUP BY teacher.Name;
SELECT teacher.Name, COUNT(teacher.Name) AS num_curriculums FROM teacher JOIN course_arrange ON course_arrange.Teacher_ID = teacher.Teacher_ID GROUP BY teacher.Name
