SELECT COUNT(DISTINCT visitor.Age) FROM visitor WHERE visitor.Age < 30
SELECT visitor.Name FROM visitor JOIN museum ON visit.Museum_ID = museum.Museum_ID WHERE visitor.Level_of_membership > 4 ORDER BY visitor.Level_of_membership DESC;
SELECT AVG(visitor.Age) FROM visitor WHERE visitor.Level_of_membership <= 4
SELECT visitor.Name, visitor.Level_of_membership FROM visitor INNER JOIN visit ON visit.visitor_ID = visitor.ID WHERE visitor.Level_of_membership > 4 ORDER BY visitor.Age ASC;
SELECT museum.Museum_ID, museum.Name, COUNT(visit.visitor_ID) AS total_visitors FROM museum INNER JOIN visit ON museum.Museum_ID = visit.Museum_ID GROUP BY museum.Museum_ID ORDER BY total_visitors DESC;
SELECT AVG(visit.Total_spent) FROM visit INNER JOIN museum ON visit.Museum_ID = museum.Museum_ID WHERE Open_Year < 2009
SELECT museum.Open_Year, visitor.Worker_Number FROM museum JOIN visitor ON museum.Museum_ID = visitor.Museum_ID;
SELECT Name FROM museum WHERE Num_of_Staff > (SELECT MIN(Num_of_Staff) FROM visit WHERE Open_Year > '2010')
SELECT v.ID, v.Name, v.Age FROM visitor v JOIN visit v2 ON v.ID = v2.visitor_ID JOIN museum m ON v2.Museum_ID = m.Museum_ID WHERE v2.Num_of_Ticket > 0;
SELECT v.ID, v.Name, v.Level_of_membership, v.Membership_level FROM visitor v JOIN visit v2 ON v.ID = v2.visitor_ID JOIN museum m ON v2.Museum_ID = m.Museum_ID WHERE v2.Total_spent = (SELECT MAX(visit.Total_spent) FROM visit v3) GROUP BY v.ID, v.Name, v.Level_of_membership, v.Membership_level
SELECT museum.Museum_ID, museum.Name, COUNT(visit.Museum_ID) AS visit_count FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID GROUP BY museum.Museum_ID ORDER BY visit_count DESC;
SELECT museum.Name FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID WHERE visit.visitor_ID IS NULL
SELECT visitor.Name, visit.Num_of_Ticket AS Num_of_Tickets FROM visitor JOIN visit ON visit.visitor_ID = visitor.ID WHERE visit.Total_spent = (SELECT MAX(visit.Total_spent) FROM visit)
SELECT AVG(visit.Num_of_Ticket), MAX(visit.Num_of_Ticket) FROM visit JOIN museum ON visit.Museum_ID = museum.Museum_ID;
SELECT SUM(visit.Total_spent) AS total_ticket_expense FROM visit JOIN museum ON visit.Museum_ID = museum.Museum_ID WHERE visit.Level_of_membership = 1;
SELECT visitor.Name FROM visitor INNER JOIN visit ON visit.visitor_ID = visitor.ID WHERE visit.Museum_ID IN (SELECT Museum_ID FROM museum WHERE Open_Year < 2009) AND visit.Museum_ID IN (SELECT Museum_ID FROM museum WHERE Open_Year > 2011)
SELECT COUNT(DISTINCT visitor.ID) FROM visit INNER JOIN museum ON visit.Museum_ID = museum.Museum_ID WHERE Open_Year > '2010'
SELECT COUNT(*) FROM museum WHERE Open_Year > 2013 OR Open_Year < 2008;
SELECT COUNT(*) AS total_participants FROM players;
SELECT COUNT(*) FROM players;
SELECT COUNT(*) AS total_competitions FROM matches;
SELECT COUNT(*) FROM matches;
SELECT players.first_name, players.birth_date, players.country_code FROM players INNER JOIN matches ON players.player_id = matches.loser_id WHERE players.country_code = 'USA' AND matches.round = '1' AND matches.year = '2023'
SELECT first_name, birth_date FROM players JOIN rankings ON players.player_id = rankings.player_id WHERE country_code = 'USA'
SELECT AVG(matches.loser_age) AS average_age FROM matches;
SELECT AVG(loser_age) AS average_losing_age, AVG(winner_age) AS average_winning_age FROM matches JOIN players ON matches.loser_id = players.player_id JOIN players ON matches.winner_id = players.player_id;
SELECT AVG(ranking_points) FROM rankings;
SELECT AVG(ranking_points) FROM rankings WHERE player_id IN (SELECT player_id FROM matches WHERE winner_id = players.player_id)
SELECT rankings.ranking, players.player_id, players.first_name, players.last_name, players.hand, players.birth_date, players.country_code, matches.loser_rank, matches.loser_rank_points, matches.loser_seed, matches.round, matches.year FROM players INNER JOIN rankings ON players.player_id = rankings.player_id ORDER BY rankings.ranking DESC;
SELECT rankings.ranking, players.player_id, players.first_name, players.last_name, players.hand, players.birth_date, players.country_code, matches.loser_rank, matches.loser_rank_points, matches.loser_seed, matches.round, matches.minute, matches.surface, matches.tourney_date, matches.tourney_id, matches.tourney_level, matches.tourney_name, matches.winner_rank, matches.winner_rank_points, matches.winner_seed, matches.year FROM players JOIN rankings ON players.player_id = rankings.player_id WHERE rankings.ranking = (SELECT MAX(ranking) FROM rankings) ORDER BY rankings.ranking DESC;
SELECT DISTINCT COUNT(DISTINCT players.country_code) FROM players;
SELECT DISTINCT COUNT(DISTINCT players.country_code) FROM players;
SELECT DISTINCT player_id FROM players JOIN rankings ON players.player_id = rankings.player_id;
SELECT COUNT(DISTINCT loser_name) FROM players JOIN matches ON matches.loser_id = players.player_id
SELECT tourney_name FROM matches INNER JOIN rankings ON matches.tourney_id = rankings.tourney_id WHERE matches.loser_hand > 10
SELECT tourney_name FROM matches INNER JOIN rankings ON matches.loser_id = rankings.player_id WHERE matches.tourney_date IS NOT NULL AND matches.tourney_id IS NOT NULL AND matches.round = 3 AND matches.loser_rank IS NOT NULL AND matches.loser_rank_points > 10;
SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.winner_id WHERE m.year IN (2013, 2016)
SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.winner_id WHERE m.year IN (2013, 2016) AND p.hand = m.loser_hand;
SELECT COUNT(*) FROM matches WHERE year IN ('2013', '2016')
SELECT COUNT(*) FROM matches WHERE year IN ('2013', '2016')
SELECT p.first_name, p.last_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON p.player_id = r.player_id WHERE m.tourney_id IN ('WTA Championships', 'Australian Open')
SELECT p.first_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON p.player_id = r.player_id WHERE m.tourney_name = 'WTA Championships' AND m.tourney_name = 'Australian Open'
SELECT players.first_name, players.country_code AS state_abbreviation FROM players INNER JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = (SELECT MAX(round) FROM matches WHERE round = matches.round AND winner_age IS NULL) AND players.birth_date IS NULL;
SELECT first_name, country_code FROM players JOIN rankings ON players.player_id = rankings.player_id ORDER BY winner_rank_points DESC LIMIT 1;
SELECT players.first_name, players.last_name, matches.loser_name, matches.loser_rank FROM players JOIN matches ON players.player_id = matches.loser_id ORDER BY players.birth_date;
SELECT p.first_name, p.last_name, p.birth_date FROM players p ORDER BY p.birth_date;
SELECT players.first_name, players.last_name, players.hand, players.birth_date FROM players JOIN matches ON players.player_id = matches.loser_id JOIN rankings ON players.player_id = rankings.player_id ORDER BY players.birth_date ASC;
SELECT p.first_name, p.last_name, p.hand, p.birth_date FROM players p ORDER BY p.birth_date
SELECT players.first_name, players.country_code, matches.tourney_name, matches.tourney_id FROM players JOIN matches ON players.player_id = matches.loser_id JOIN rankings ON players.player_id = rankings.player_id WHERE matches.tourney_id = (SELECT MAX(tourney_id) FROM matches) ORDER BY players.country_code;
SELECT players.first_name, players.country_code FROM players JOIN rankings ON players.player_id = rankings.player_id WHERE rankings.ranking = (SELECT MAX(ranking) FROM rankings)
SELECT year, COUNT(*) AS num_competitions FROM matches GROUP BY year ORDER BY num_competitions DESC LIMIT 1
SELECT year, COUNT(*) AS num_competitions FROM matches GROUP BY year ORDER BY num_competitions DESC;
SELECT players.first_name, matches.winner_ranking_points AS winner_rank_points FROM players JOIN matches ON matches.winner_id = players.player_id WHERE matches.best_of = (SELECT MAX(best_of) FROM matches WHERE matches.best_of = 1);
SELECT p.first_name, p.last_name, m.round, m.rank_points, m.winner_rank_points FROM players p JOIN matches m ON m.winner_id = p.player_id WHERE m.rank_points = (SELECT MAX(rank_points) FROM matches) GROUP BY p.first_name, p.last_name, m.round, m.rank_points, m.winner_rank_points;
SELECT winner_name FROM matches JOIN players ON matches.winner_id = players.player_id WHERE matches.tourney_id IN (SELECT tourney_id FROM rankings WHERE tours = 'Australian Open tourney' AND ranking_points = (SELECT MAX(ranking_points) FROM rankings WHERE tours = 'Australian Open tourney'))
SELECT winner_name FROM matches INNER JOIN players ON matches.winner_id = players.player_id WHERE matches.tourney_id = (SELECT tourney_id FROM rankings WHERE ranking = 1 ORDER BY ranking_points DESC LIMIT 1)
SELECT players.first_name, players.last_name, matches.minutes FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.minutes = (SELECT MAX(minutes) FROM matches) ORDER BY matches.minutes DESC;
SELECT p.first_name, p.last_name AS player_name, m.loser_name AS loser_name FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.round = (SELECT MAX(round) FROM matches WHERE round IS NOT NULL);
SELECT players.first_name, AVG(rankings.ranking_points) AS average_ranking_points FROM players INNER JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.first_name
SELECT p.first_name, p.last_name, AVG(r.ranking_points) AS average_rankings FROM players p JOIN rankings r ON p.player_id = r.player_id GROUP BY p.first_name, p.last_name
SELECT p.first_name, p.last_name, SUM(r.ranking_points) AS total_ranking_points FROM players p JOIN rankings r ON p.player_id = r.player_id GROUP BY p.first_name, p.last_name
SELECT players.first_name, players.last_name, SUM(ranking_points) AS total_ranking_points FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.first_name, players.last_name;
SELECT COUNT(*) AS total_participants FROM players;
SELECT COUNT(DISTINCT players.country_code) AS total_participants, players.country_code AS country FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.country_code
SELECT players.country_code FROM players JOIN rankings ON rankings.player_id = players.player_id WHERE rankings.ranking = (SELECT MAX(ranking) FROM rankings)
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id GROUP BY player_id ORDER BY ranking_points DESC LIMIT 1
SELECT player.country_code FROM players JOIN matches ON matches.winner_id = players.player_id WHERE matches.round = '2023' AND matches.minutes > 3000
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = 1 AND matches.minutes > 5000000
SELECT COUNT(*) AS total_trips FROM rankings INNER JOIN matches ON rankings.player_id = matches.loser_id;
SELECT DISTINCT player_id, ranking_points, COUNT(*) AS total_travels FROM rankings INNER JOIN players ON rankings.player_id = players.player_id GROUP BY player_id
SELECT year, COUNT(*) AS number_of_games_per_year FROM matches GROUP BY year
SELECT year, COUNT(*) AS total_games FROM matches GROUP BY year;
SELECT p.first_name, p.last_name, r.ranking FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking ASC LIMIT 3;
SELECT p.first_name, p.last_name, r.ranking FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking ASC LIMIT 3;
SELECT COUNT(DISTINCT players.player_id) FROM players JOIN matches ON matches.winner_id = players.player_id JOIN rankings ON rankings.player_id = players.player_id WHERE rankings.ranking = 1;
SELECT COUNT(*) FROM players INNER JOIN matches ON players.player_id = matches.winner_id;
SELECT p.first_name, p.country_code, m.round, m.rank_points, p.first_name, p.country_code, p.first_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON m.player_id = r.player_id WHERE r.ranking_points = (SELECT MAX(ranking_points) FROM rankings) ORDER BY r.ranking_points DESC;
SELECT p.first_name, p.country_code, m.winner_rank_points AS winner_rank_points FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON m.match_num = r.ranking_date WHERE r.ranking = (SELECT MAX(ranking_points) FROM rankings r) ORDER BY p.first_name, p.country_code LIMIT 1;
SELECT COUNT(DISTINCT players.hand) AS number_of_participants FROM players;
SELECT DISTINCT hand, COUNT(*) AS participant_count FROM players JOIN matches ON players.player_id = matches.loser_id GROUP BY hand
SELECT COUNT(*) FROM ship WHERE disposition_of_ship = 'Captured'
SELECT name, tonnage FROM ship ORDER BY name DESC;
SELECT battle.name, battle.date, battle.result FROM battle;
SELECT MAX(killed), MIN(killed) FROM death;
SELECT AVG(death.injured) FROM death JOIN battle ON death.caused_by_ship_id = battle.id;
SELECT d.note, s.name, s.tonnage FROM ship s JOIN death d ON s.id = d.caused_by_ship_id WHERE s.tonnage = 't' GROUP BY d.note, s.name, s.tonnage
SELECT battle.name, battle.result FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE battle.bulgarian_commander != 'Boril'
SELECT battle.id, battle.name, ship.id, ship.name FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE ship_type = 'Brig' AND result IS NULL;
SELECT b.id, b.name, d.killed, d.injured FROM battle b JOIN death d ON b.id = d.caused_by_ship_id WHERE d.killed > 10 OR d.injured > 10;
SELECT battle.id, name, ship.id, ship.name, ship.tonnage, ship.ship_type, ship.location, ship.disposition_of_ship, death.id, death.note, death.killed, death.injured, death.caused_by_ship_id, death.result FROM battle JOIN ship ON battle.id = ship.lost_in_battle JOIN death ON ship.id = death.caused_by_ship_id GROUP BY battle.id, name, ship.id, ship.name, ship.tonnage, ship.ship_type, ship.location, ship.disposition_of_ship, death.id, death.note, death.killed, death.injured, death.caused_by_ship_id, death.result ORDER BY death.injured DESC;
SELECT DISTINCT name FROM battle JOIN ship ON battle.id = ship.lost_in_battle JOIN death ON ship.id = death.caused_by_ship WHERE bulgarian_commander = 'Kaloyan' AND latin_commander = 'Baldwin I';
SELECT COUNT(DISTINCT battle.id) FROM battle;
SELECT COUNT(*) FROM battle WHERE result = 'lost' AND (SELECT COUNT(*) FROM ship WHERE tonnage = '225' AND lost_in_battle IS NOT NULL)
SELECT b.name, b.date, s.name, d.note FROM battle b JOIN ship s ON b.id = s.lost_in_battle JOIN death d ON s.id = d.caused_by_ship_id WHERE b.name = 'Lettice' OR b.name = 'HMS Atalanta' AND d.note IS NOT NULL;
SELECT battle.name, battle.result, battle.bulgarian_commander FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE ship.location = 'English Channel' AND battle.result IS NULL;
SELECT death.note FROM death JOIN ship ON death.caused_by_ship_id = ship.id JOIN battle ON ship.lost_in_battle = battle.id WHERE battle.name LIKE '%East%';
SELECT Addresses.address_id, Addresses.line_1, Addresses.line_2 FROM Addresses;
SELECT line_1, line_2 FROM Addresses ORDER BY line_1, line_2 LIMIT 2
SELECT COUNT(DISTINCT course_name) FROM Courses;
SELECT COUNT(*) FROM Courses;
SELECT course_description, other_details FROM Courses ORDER BY course_description;
SELECT course_description FROM Courses;
SELECT zip_postcode FROM Addresses WHERE city = 'Port Chelsea'
SELECT zip_postcode FROM Addresses WHERE city = 'Port Chelsea' AND state_province_county IS NULL;
SELECT DISTINCT d.department_name, d.department_id FROM Departments d JOIN Degree_Programs d2 ON d.department_id = d2.department_id;
SELECT D.department_name, MAX(S.section_name) AS most_degrees_name FROM Departments D JOIN Degree_Programs D2 ON D.department_id = D2.department_id GROUP BY D.department_id;
SELECT COUNT(DISTINCT department_id) FROM Departments
SELECT COUNT(DISTINCT department_id) FROM Departments;
SELECT COUNT(DISTINCT course_name) FROM Courses;
SELECT COUNT(DISTINCT course_description) FROM Courses;
SELECT COUNT(DISTINCT degree_program_id) FROM Degree_Programs;
SELECT COUNT(*) FROM Departments;
SELECT course_name, section_description FROM Sections INNER JOIN Courses ON Sections.course_id = Courses.course_id;
SELECT course_name, section_description, other_details FROM Sections INNER JOIN Courses ON Sections.course_id = Courses.course_id;
SELECT course_name, course_id FROM Courses INNER JOIN Sections ON Sections.course_id = Courses.course_id WHERE Sections.section_description IS NULL AND Sections.section_name IS NULL AND Sections.section_description IS NULL AND Sections.section_name IS NULL;
SELECT course_name, course_id FROM Courses INNER JOIN Sections ON Sections.course_id = Courses.course_id WHERE Sections.section_description LIKE '%less than 2%'
SELECT section_name FROM Sections ORDER BY section_name REVERSE;
SELECT section_name, section_description, reverse_order FROM Sections ORDER BY section_name DESC;
SELECT s.first_name, s.student_id FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Departments d ON ssec.degree_program_id = d.department_id JOIN Degree_Programs dp ON d.department_id = dp.department_id;
SELECT s.semester_name, s.student_id, s.first_name, s.middle_name, s.last_name FROM Semesters s JOIN Student_Enrolment_Courses c ON s.semester_id = c.semester_id JOIN Courses ON c.course_id = Courses.course_id JOIN Students ON c.student_id = Students.student_id WHERE c.student_enrolment_id = (SELECT MAX(student_enrolment_id) FROM Student_Enrolment_Courses) ORDER BY s.semester_name, s.student_id, s.first_name, s.middle_name, s.last_name;
SELECT course_description, other_details FROM Courses JOIN Student_Enrolment_Courses ON Courses.course_id = Student_Enrolment_Courses.course_id JOIN Courses ON Student_Enrolment_Courses.course_id = Courses.course_id WHERE course_name LIKE '%computer%'
SELECT D.department_name, D.department_description, D.degree_program_id, D.degree_summary_name, D.degree_summary_description FROM Departments D JOIN Degree_Programs D2 ON D.department_id = D2.department_id WHERE D2.degree_program_id = (SELECT degree_program_id FROM Degree_Programs WHERE degree_summary_name = 'computer')
SELECT s.first_name, s.middle_name, s.last_name, s.student_id FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Degree_Programs dp ON dp.department_id = s.department_id JOIN Departments d ON dp.department_id = d.department_id JOIN Transcript_Contents tc ON sc.student_course_id = tc.student_course_id JOIN Transcripts t ON tc.transcript_id = t.transcript_id;
SELECT S.first_name, S.middle_name, S.last_name, S.student_id, D.department_id, D.department_name FROM Students S JOIN Degree_Programs D ON S.student_id = D.degree_program_id WHERE D.department_id IN (SELECT department_id FROM Departments) AND D.degree_program_id IN (SELECT degree_program_id FROM Degree_Programs) AND D.degree_summary_name = '2 degree programs' ORDER BY S.first_name, S.middle_name, S.last_name
SELECT first_name, middle_name, last_name FROM Students ORDER BY last_name ASC;
SELECT S.first_name, S.middle_name, S.last_name, S.other_student_details FROM Students S JOIN Addresses A ON S.current_address_id = A.address_id JOIN Departments D ON S.department_id = D.department_id JOIN Degree_Programs DP ON S.department_id = DP.department_id JOIN Courses C ON S.current_address_id = C.course_id JOIN Sections S1 ON S.section_id = S1.section_id JOIN Transcripts T ON S.section_id = T.transcript_id JOIN Transcript_Contents TC ON T.transcript_id = TC.transcript_id;
SELECT D.degree_summary_name, COUNT(D.degree_program_id) AS total_students_enrolled FROM Degree_Programs D JOIN Students S ON D.department_id = S.department_id GROUP BY D.degree_summary_name ORDER BY total_students_enrolled DESC;
SELECT DISTINCT Degree_Programs.degree_summary_name, COUNT(CASE WHEN Semester_id IS NULL THEN 0 ELSE 1 END) AS student_count FROM Degree_Programs JOIN Semester_Enrollments ON Degree_Programs.degree_program_id = Semester_Enrollments.degree_program_id GROUP BY Degree_Programs.degree_summary_name ORDER BY student_count DESC LIMIT 1;
SELECT D.degree_program_id, D.department_name, D.degree_summary_name, D.degree_summary_description, S.summary FROM Degree_Programs D JOIN Departments D2 ON D.department_id = D2.department_id JOIN Students S ON D.degree_program_id = S.student_id JOIN Student_Enrolment_Courses SC ON S.student_id = SC.student_course_id JOIN Courses C ON SC.course_id = C.course_id JOIN Sections S2 ON C.course_id = S2.course_id JOIN Semester_Semesters SS ON S2.semester_id = SS.semester_id WHERE D.degree_program_id = (SELECT degree_program_id FROM Degree_Programs ORDER BY COUNT(S.summary) DESC LIMIT 1)
SELECT D.degree_program_id, D.degree_summary_name, D.degree_summary_description, D.other_details FROM Degree_Programs D WHERE D.degree_program_id = (SELECT degree_program_id FROM Degree_Programs ORDER BY COUNT(*) DESC LIMIT 1)
SELECT s.id, s.first_name, s.middle_name, s.last_name, s.student_enrollments_count, s.student_id FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON c.course_id = ssec.course_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id GROUP BY s.id, s.first_name, s.middle_name, s.last_name, s.student_enrollments_count, s.student_id ORDER BY s.student_enrollments_count DESC;
SELECT s.middle_name, s.id, COUNT(se.semester_id) AS enrollments FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Student_Enrolment se ON sc.student_enrolment_id = se.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON se.semester_id = ssec.semester_id JOIN Semesters ssem ON ssem.semester_id = se.semester_id GROUP BY s.middle_name, s.id ORDER BY enrollments DESC;
SELECT section_name FROM Sections WHERE section_description IS NULL;
SELECT DISTINCT s.first_name, s.last_name FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id WHERE s.date_left IS NULL;
SELECT course_name FROM Courses WHERE course_name IS NOT NULL;
SELECT course_name FROM Courses INNER JOIN Sections ON Courses.course_id = Sections.course_id WHERE Sections.semester_id = 1;
SELECT course_name, COUNT(*) AS enrollments FROM Courses INNER JOIN Student_Enrolment_Courses ON Courses.course_id = Student_Enrolment_Courses.course_id INNER JOIN Student_Enrolment ON Student_Enrolment_Courses.student_enrolment_id = Student_Enrolment.student_id GROUP BY course_name ORDER BY enrollments DESC LIMIT 1;
SELECT course_name, COUNT(*) AS student_count FROM Courses JOIN Student_Enrolment_Courses ON Courses.course_id = Student_Enrolment_Courses.course_id JOIN Students ON Student_Enrolment_Courses.student_enrolment_id = Students.student_id GROUP BY course_name ORDER BY student_count DESC LIMIT 1;
SELECT DISTINCT s.last_name FROM Addresses s JOIN Students s ON s.address_id = Students.current_address_id JOIN Courses c ON s.current_address_id = Addresses.address_id JOIN Departments d ON s.current_address_id = Addresses.address_id JOIN Degree_Programs dp ON d.department_id = dp.department_id JOIN Sections s2 ON s.current_address_id = Addresses.address_id JOIN Semesters s3 ON s.current_address_id = Addresses.address_id JOIN Student_Enrolment_Courses sc ON s.current_address_id = Student_Enrolment_Courses.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Student_Enrolment se ON Student_Enrolment_Courses.course_id = se.course_id JOIN Transcripts t ON se.course_id = t.transcript_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id WHERE s.state_province_county = 'North Carolina' AND s.state_province_county = 'North Carolina' AND s.date_left IS NULL;
SELECT DISTINCT Students.last_name FROM Addresses INNER JOIN Students ON Addresses.address_id = Students.current_address_id WHERE Addresses.state_province_county = 'North Carolina' AND Addresses.country = 'US' AND Students.date_first_registered IS NULL;
SELECT S.student_id, S.date_first_registered, S.date_left, S.address_id, S.first_name, S.middle_name, S.last_name, S.cell_mobile_number, S.email_address, S.ssn, S.date_first_registered, S.date_left, S.other_address_details FROM Students S WHERE S.date_first_registered IS NOT NULL AND S.date_left IS NOT NULL AND S.date_first_registered >= DATE_SUB(CURDATE(), INTERVAL 2 DAY) ORDER BY S.date_first_registered
SELECT s.student_id, s.date_first_registered, s.date_left, s.first_name, s.last_name, s.middle_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Semesters ssem ON s.section_id = ssem.semester_id JOIN Departments d ON ssem.department_id = d.department_id JOIN Degree_Programs dp ON ssem.department_id = dp.department_id JOIN Courses c ON sc.course_id = c.course_id JOIN Transcripts tr ON sc.transcript_id = tr.transcript_id JOIN Transcript_Contents tc ON sc.transcript_id = tc.transcript_id WHERE s.date_left > s.date_first_registered AND s.date_left > s.date_first_registered;
SELECT s.last_name, s.cell_mobile_number FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id WHERE s.first_name = 'Timmothy' AND s.last_name = 'Ward';
SELECT student_id, first_name, last_name, cell_mobile_number FROM Students WHERE first_name = 'Timothy' AND last_name = 'Ward';
SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left FROM Students s WHERE s.date_first_registered = (SELECT date_first_registered FROM Students) ORDER BY s.date_first_registered ASC
