SELECT s.last_name, s.first_name FROM Students s WHERE s.permanent_address_id = s.current_address_id ORDER BY s.last_name;
SELECT s.first_name, s.last_name, s.middle_name, s.other_student_details FROM Students s WHERE s.permanent_address_id = s.current_address_id AND s.permanent_address_id IS NOT NULL AND s.permanent_address_id = s.permanent_address_id;
SELECT s.place_id, s.lines FROM Addresses s JOIN Student_Enrolment_Courses sc ON s.address_id = sc.student_enrolment_id JOIN Sections sc2 ON sc2.course_id = sc.course_id JOIN Courses c ON sc2.course_id = c.course_id JOIN Departments d ON c.department_id = d.department_id JOIN Degree_Programs dp ON c.department_id = dp.department_id JOIN Transcripts t ON sc2.course_id = t.transcript_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id GROUP BY s.place_id, s.lines ORDER BY s.place_id ASC;
SELECT S.id, S.line_1, S.line_2 FROM Addresses S JOIN Student_Enrolment_Courses SC ON S.address_id = SC.student_enrolment_id JOIN Courses C ON SC.course_id = C.course_id JOIN Sections S2 ON S2.section_id = S.section_id JOIN Semesters S3 ON S3.semester_id = S2.semester_id JOIN Departments D ON D.department_id = S2.department_id JOIN Degree_Programs DP ON DP.department_id = D.department_id JOIN Student_Enrolment_Courses SC2 ON S2.section_id = SC2.section_id JOIN Courses C2 ON SC2.course_id = C2.course_id JOIN Sections S32 ON S32.section_id = S32.section_id JOIN Semesters S33 ON S33.semester_id = S33.semester_id JOIN Departments D2 ON D2.department_id = D2.department_id JOIN Degree_Programs DP2 ON DP2.department_id = D2.department_id;
SELECT AVG(transcript_date) AS average_record_date FROM Transcripts;
SELECT AVG(date_left) AS average_student_record_date FROM Students;
SELECT s.date_left, s.first_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered FROM Students s JOIN Transcripts t ON s.student_id = t.student_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id JOIN Student_Enrolment_Courses se ON tc.student_course_id = se.student_course_id JOIN Courses c ON se.course_id = c.course_id JOIN Sections s1 ON s1.section_id = s.section_id JOIN Semesters s2 ON s1.semester_id = s2.semester_id JOIN Departments d ON s1.department_id = d.department_id JOIN Degree_Programs dp ON s1.degree_program_id = dp.degree_program_id;
SELECT MIN(transcript_date) AS earliest_date, MAX(transcript_date) AS latest_date
SELECT COUNT(*) FROM Students;
SELECT COUNT(*) FROM Students;
SELECT MAX(transcript_date) AS last_student_record_release_date FROM Transcripts;
SELECT MAX(transcript_date) FROM Transcripts;
SELECT DISTINCT student_enrolment_id, course_id FROM Student_Enrolment_Courses JOIN Courses ON Student_Enrolment_Courses.course_id = Courses.course_id;
SELECT MAX(course_id), MAX(semester_id) FROM Student_Enrolment_Courses;
SELECT student_id, date_first_registered, date_left FROM Students WHERE date_left IS NULL AND date_first_registered IS NOT NULL ORDER BY date_first_registered ASC LIMIT 1;
SELECT student_id, date_first_registered, date_left, student_id, date_first_registered, date_left FROM Students WHERE date_left IS NULL ORDER BY date_first_registered ASC LIMIT 1;
