SELECT o.owner_id, t.zip_code FROM Owners o INNER JOIN Treatments t ON o.owner_id = t.dog_id INNER JOIN Dogs d ON d.owner_id = o.owner_id INNER JOIN Sizes s ON d.size_code = s.size_code INNER JOIN Breeds b ON d.breed_code = b.breed_code INNER JOIN Professionals p ON t.professional_id = p.professional_id;
SELECT Dogs.owner_id, Dogs.zip_code FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Treatments ON Treatments.dog_id = Dogs.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id GROUP BY Dogs.owner_id, Dogs.zip_code ORDER BY Charges.charge_amount DESC LIMIT 1;
SELECT o.owner_id, d.cell_number FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id WHERE d.abandoned_yn = 'N' AND d.date_of_birth IS NOT NULL;
SELECT Dogs.id, Dogs.cell_number FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id WHERE Dogs.abandoned_yn = 'Y' OR Dogs.date_departed IS NOT NULL;
SELECT o.first_name, o.last_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Charges c ON d.dog_id = c.charge_id WHERE c.charge_amount < (SELECT AVG(charge_amount) FROM Charges)
SELECT o.first_name, o.last_name, d.name, d.age, d.date_of_birth, d.gender, d.weight, d.date_arrived, d.date_departed FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t1 ON t.treatment_type_code = t1.treatment_type_code JOIN Charges c ON t.cost_of_treatment = c.charge_amount WHERE t.cost_of_treatment < (SELECT AVG(c.charge_amount) FROM Charges c) GROUP BY o.first_name, o.last_name, d.name, d.age, d.date_of_birth, d.gender, d.weight, d.date_arrived, d.date_departed
SELECT Dogs.date_of_birth, Professionals.first_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id;
SELECT Dogs.name, Professionals.first_name AS operating_veterinarian_given_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id;
SELECT Dogs.dog_id, Dogs.breed_code, Dogs.size_code, Dogs.name, Dogs.date_of_birth, Dogs.gender, Dogs.weight, Charges.charge_type, Charges.charge_amount, Treatments.treatment_type_code, Treatments.cost_of_treatment FROM Dogs JOIN Charges ON Dogs.dog_id = Charges.charge_id JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount, Charges.charge_type FROM Dogs JOIN Treatment_Types ON Dogs.breed_code = Treatment_Types.treatment_type_code JOIN Charges ON Dogs.dog_id = Charges.charge_id;
SELECT Dogs.first_name, Dogs.last_name, Sizes.size_code AS size_code FROM Dogs INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code;
SELECT Dogs.first_name, Dogs.last_name, Dogs.size_code AS dog_size FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Owners.first_name, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Treatments.treatment_type_description FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id;
SELECT Dogs.name, Treatments.date_of_treatment FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Treatments.cost_of_treatment IS NULL AND Treatments.treatment_type_code = 'Rare' AND Treatments.date_of_treatment IS NOT NULL;
SELECT Dogs.name, Treatments.date_of_treatment FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id WHERE Treatments.cost_of_treatment IS NULL;
SELECT o.first_name, d.name AS dog_name FROM Owners o INNER JOIN Dogs d ON o.owner_id = d.owner_id WHERE o.state = 'Virginia' AND d.state = 'Virginia' AND d.abandoned_yn = 'N' AND d.name IS NOT NULL;
SELECT Dogs.name, Owners.first_name, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Virginia' AND Dogs.abandoned_yn = 'Y' AND Dogs.treatment_type_code = 'TREATMENT_TYPE_1'
SELECT Dogs.date_of_birth, Dogs.date_departed, Dogs.date_arrived FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.date_of_departed, Dogs.date_of_birth FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Breeds ON Dogs.breed_code = Breeds.breed_code INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code;
