SELECT COUNT(*) AS Count FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID;
SELECT DISTINCT singer.Name AS Most_Common_Country, singer.Birth_Year AS Birth_Year, singer.Net_Worth_Millions AS Net_Worth_Millions, singer.Citizenship AS Citizenship FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY singer.Name, singer.Birth_Year, singer.Net_Worth_Millions, singer.Citizenship ORDER BY singer.Name ASC;
